#!/bin/sh
# OBD II Lab: complete, offline Linux launcher.
# Save this one file in any folder and run: bash run.sh
# Requires Python 3.10 or newer. No extra packages or downloads are needed.
set -eu
if ! command -v python3 >/dev/null 2>&1; then
    printf '%s\n' 'Python 3.10 or newer is needed to run the simulator.' >&2
    printf '%s\n' 'Install Python 3, then run: bash run.sh' >&2
    exit 1
fi
export PYTHONDONTWRITEBYTECODE=1
exec python3 -u - "$0" "$@" <<'PYTHON'
import sys

if sys.version_info < (3, 10):
    print("Python 3.10 or newer is required. Found Python " + sys.version.split()[0] + ".", file=sys.stderr)
    print("Install a newer Python 3, then run: bash run.sh", file=sys.stderr)
    raise SystemExit(1)

import base64
import hashlib
import io
import os
from pathlib import Path, PurePosixPath
import runpy
import signal
import stat
import tempfile
import zipfile

EXPECTED_ARCHIVE_SHA256 = "f7a39a5a02b01e1844c68fbfc40807bc5277a1d66010e9f32d21776ca427f3fe"
sys.dont_write_bytecode = True

def stop_requested(_signum, _frame):
    raise KeyboardInterrupt

signal.signal(signal.SIGTERM, stop_requested)

def unpack_bundle(destination):
    try:
        source = Path(sys.argv[1]).resolve().read_bytes()
        encoded = source.split(b"\n: <<'OBDII_PAYLOAD'\n", 1)[1]
        encoded, tail = encoded.rsplit(b"\nOBDII_PAYLOAD", 1)
        if tail.strip():
            raise ValueError("unexpected text after the bundled files")
        payload = base64.b64decode(b"".join(encoded.split()), validate=True)
    except (OSError, ValueError, IndexError) as exc:
        raise ValueError("The download is incomplete or damaged. Download run.sh again.") from exc
    if hashlib.sha256(payload).hexdigest() != EXPECTED_ARCHIVE_SHA256:
        raise ValueError("The bundled files did not pass their checksum. Download run.sh again.")
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        names = set()
        for item in archive.infolist():
            relative = PurePosixPath(item.filename)
            if (item.is_dir() or relative.is_absolute() or ".." in relative.parts
                    or "\\" in item.filename or "\x00" in item.filename
                    or relative.as_posix() != item.filename or not relative.parts
                    or stat.S_ISLNK(item.external_attr >> 16) or item.filename in names):
                raise ValueError("The bundled file layout is invalid. Download run.sh again.")
            names.add(item.filename)
        required = {"launcher.py", "run.py", "obdii_lab/server.py", "web/index.html", "SHA256SUMS.txt"}
        if not required.issubset(names):
            raise ValueError("The download is missing simulator files. Download run.sh again.")
        checksums = {}
        for line in archive.read("SHA256SUMS.txt").decode("utf-8").splitlines():
            digest, name = line.split("  ", 1)
            if name in checksums or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
                raise ValueError("The bundled checksum list is invalid. Download run.sh again.")
            checksums[name] = digest
        if set(checksums) != names - {"SHA256SUMS.txt"}:
            raise ValueError("The bundled checksum list is incomplete. Download run.sh again.")
        for item in archive.infolist():
            content = archive.read(item)
            if item.filename != "SHA256SUMS.txt" and hashlib.sha256(content).hexdigest() != checksums[item.filename]:
                raise ValueError("A bundled file is damaged. Download run.sh again.")
            target = destination.joinpath(*PurePosixPath(item.filename).parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)
            target.chmod(0o755 if (item.external_attr >> 16) & 0o111 else 0o644)

def main():
    previous_directory = Path.cwd()
    with tempfile.TemporaryDirectory(prefix="obdii-lab-") as temporary:
        destination = Path(temporary)
        try:
            unpack_bundle(destination)
            sys.path.insert(0, str(destination))
            sys.argv = ["run.sh", *sys.argv[2:]]
            os.chdir(destination)
            runpy.run_path(str(destination / "launcher.py"), run_name="__main__")
        finally:
            os.chdir(previous_directory)

try:
    main()
except KeyboardInterrupt:
    print("\nLab stopped.")
except (OSError, ValueError, UnicodeError, zipfile.BadZipFile) as exc:
    print("Could not prepare the simulator: " + str(exc), file=sys.stderr)
    raise SystemExit(1)
